from harness.gramps_instance import OWNER_PW, OWNER_USER, ROLE_OWNER, GrampsInstance
from harness.mcp_container import ImageRef, McpContainer, container_name
from harness.rest import GrampsRest
from harness.runid import new_runid

# Needs a live Gramps Web instance, not merely Docker. Declared rather than inferred: the
# required CI leg selects `-m 'e2e and not gramps'`, and a module that forgets this marker
# would drag a whole instance bring-up into the job that is meant to need no services.
pytestmark = pytest.mark.gramps

TREE_FILE = Path(__file__).parent / "fixtures" / "synthetic-tree.gramps"
COUSINS_FILE = Path(__file__).parent / "fixtures" / cast.COUSINS["filename"]
PAGESIZE = 20
UNKNOWN_SEX = 2


@pytest.fixture(scope="module")
def instance() -> Iterator[GrampsInstance]:
    started = GrampsInstance(new_runid())
    started.start()
    assert started.add_user(OWNER_USER, OWNER_PW, ROLE_OWNER)["rc"] == 0
    try:
        yield started
    finally:
        started.teardown()


@pytest.fixture(scope="module")
def imported(
    instance: GrampsInstance, mcp_image: ImageRef, tmp_path_factory: pytest.TempPathFactory
) -> Iterator[GrampsRest]:
    """Import the committed fixture through `gramps_import_file`, then hand over the oracle."""
    backup = tmp_path_factory.mktemp("backup")
    shutil.copy(TREE_FILE, backup / TREE_FILE.name)
    backup.chmod(0o777)  # the container runs as a different uid than the test process

    mcp = McpContainer(
        container_name(instance.runid, "fixture"),
        mcp_image.run_reference,
        {
            "GRAMPS_BASE_URL": instance.internal_url,
            "GRAMPS_USERNAME": OWNER_USER,
            "GRAMPS_PASSWORD": OWNER_PW,
            "GRAMPS_BACKUP_DIR": "/data",
        },
        network=instance.network,
        mounts=((str(backup), "/data"),),
        runid=instance.runid,
    )
    try:
        result = mcp.call("gramps_import_file", {"filename": TREE_FILE.name}, timeout=600)
        assert not result.is_error, result.text
        yield GrampsRest(instance.url, OWNER_USER, OWNER_PW)
    finally:
        assert mcp.close() == [], "the MCP container outlived its test"


def test_both_committed_inputs_are_plain_xml() -> None:
    """A gzipped export is not diff-stable — its wrapper carries a UUID, so a rebuild would
    show a wall of changed bytes whether or not the tree changed."""
    for path in (TREE_FILE, COUSINS_FILE):
        head = path.read_bytes()[:64]

        assert head[:2] != b"\x1f\x8b", f"{path.name} is still gzipped"
        assert head.startswith(b"<?xml"), path.name


def test_every_namespace_is_larger_than_one_page() -> None:
    """Under 21 the `len(unpaginated list)` assumption in the product is untestable."""
    assert cast.COUNTS["people"] > PAGESIZE
    assert cast.COUNTS["families"] > PAGESIZE
    assert cast.COUNTS["sources"] > PAGESIZE


def test_the_import_lands_exactly_the_cast(imported: GrampsRest) -> None:
    """Every namespace, not just the three the cast is named for. Gramps records a repaired
    dangling reference as an extra **note**, so the note count is what turns a subtly damaged
    fixture red — measured: deleting a whole `<family>` element leaves people, families and
    sources untouched and shows up only there."""
    assert imported.object_counts() == cast.COUNTS


def test_the_unpaginated_lists_agree_with_the_counts(imported: GrampsRest) -> None:
    """The product counts by `len(list)`; if the server ever paginates that list by default,
    every count-based guard in the server silently starts reporting 20."""
    counts = imported.object_counts()

    assert len(imported.people()) == counts["people"]
    assert len(imported.families()) == counts["families"]
    assert len(imported.sources()) == counts["sources"]


def test_the_gramps_ids_survive_the_import(imported: GrampsRest) -> None:
    """Ids are assigned by the server in creation order and are the cast's whole point — an
    import that renumbers them would leave every later test asserting against nothing."""
    landed = {record["gramps_id"] for record in imported.people()}

    assert {person["gramps_id"] for person in cast.PEOPLE} <= landed
    assert cast.PEOPLE[0]["gramps_id"] == "I0000", "ids start at I0000, not I0001"


def test_a_person_reads_back_with_the_name_the_cast_records(imported: GrampsRest) -> None:
    expected = cast.PEOPLE[0]
    person = imported.person(str(expected["gramps_id"]))
    name = person["primary_name"]

    assert name["first_name"] == expected["first_name"]
    assert name["surname_list"][0]["surname"] == expected["surname"]
    assert person["gender"] == expected["gender"]


def test_every_family_reads_back_with_the_members_the_cast_records(imported: GrampsRest) -> None:
    """Counting families cannot detect a damaged one. Each person carries a `<parentin>` or
    `<childof>` reference, so deleting a whole `<family>` element leaves the count at 21 — the
    importer rebuilds one from the dangling reference. Measured: that mutation survived a
    count-only assertion. Only the membership catches it."""
    families = {family["gramps_id"]: family for family in imported.families()}
    person_id = {person["handle"]: person["gramps_id"] for person in imported.people()}

    for expected in cast.FAMILIES:
        family = families[str(expected["gramps_id"])]
        parents = {
            person_id.get(handle)
            for handle in (family["father_handle"], family["mother_handle"])
            if handle
        }
        children = {person_id.get(ref["ref"]) for ref in family["child_ref_list"]}

        assert parents == {expected["spouse_a"], expected["spouse_b"]} - {None}
        assert children == set(expected["children"])


def test_the_families_carry_their_children(imported: GrampsRest) -> None:
    """Without child links the fixture is 21 unrelated couples, and every descendant or
    ancestor test built on it would walk a graph with no edges."""
    with_children = [family for family in imported.families() if family["child_ref_list"]]

    assert len(with_children) == len([f for f in cast.FAMILIES if f["children"]])
    assert with_children, "no family has a child"


def test_the_household_missing_a_parent_reads_back_missing_it(imported: GrampsRest) -> None:
    """uc14 asks the model to put a father on record, and its whole discriminating power is
    that `set_family_parent` fills an *existing* empty slot while `add_family` would build a
    second household beside it. With both slots filled in the fixture there is nothing to fill.

    That the surviving parent lands in the mother slot is the product's documented rule for a
    single female spouse (`server.py:134-141`), so it is asserted rather than assumed."""
    declared = [family for family in cast.FAMILIES if family["spouse_b"] is None]
    assert len(declared) == 1, "the fixture no longer holds exactly one one-parent household"
    families = {family["gramps_id"]: family for family in imported.families()}
    household = families[str(declared[0]["gramps_id"])]

    assert household["mother_handle"], "the single spouse is not in the mother slot"
    assert not household["father_handle"], "the slot uc14 exists to fill is already taken"


def test_the_census_five_are_the_only_records_without_a_sex(imported: GrampsRest) -> None:
    """uc22 turns `2=Unknown` into three females and two males through one bulk call. If
    anybody else were Unknown, "nobody else moved" would stop being decidable."""
    declared = {p["gramps_id"] for p in cast.PEOPLE if p["gender"] == UNKNOWN_SEX}
    landed = {p["gramps_id"] for p in imported.people() if p["gender"] == UNKNOWN_SEX}

    assert landed == declared
    assert len(landed) == 5


def test_the_name_history_reads_back_as_plain_strings(imported: GrampsRest) -> None:
    """The Stage-2 design left this open (`[U]` #1) and uc13 — the sharpest assertion in the
    suite — depends on the answer: the client *writes* a bare string
    (`gramps_client.py:269`), and if the API normalised it into a `NameType` object every
    assertion about `Married Name` would have to go through that shape instead. Measured at
    build time into `cast.NAME_TYPES`; pinned here so a server upgrade that starts
    normalising is a red test rather than a silently rewritten use case."""
    declared = next(p for p in cast.PEOPLE if p["gramps_id"] == cast.NAME_TYPES["gramps_id"])
    person = imported.person(str(declared["gramps_id"]))
    alternate = person["alternate_names"][0]

    assert person["primary_name"]["type"] == cast.NAME_TYPES["primary"] == declared["name_type"]
    assert alternate["type"] == declared["alternate_names"][0]["name_type"]
    assert alternate["surname_list"][0]["surname"] == declared["alternate_names"][0]["surname"]


def test_exactly_one_note_carries_the_year_uc17_rewrites(imported: GrampsRest) -> None:
    """uc17 asserts that the body came back byte-identical except `1912` → `1913`, which is
    only unfakeable while `1912` appears once in the whole tree: a second occurrence would
    make "the model edited the right article" undecidable from the tree alone."""
    bodies = [(note.get("text") or {}).get("string", "") for note in imported.notes()]

    assert sum(body.count("1912") for body in bodies) == 1
    assert sum(body.count("1913") for body in bodies) == 0


def test_both_tags_the_tools_create_are_already_seeded(imported: GrampsRest) -> None:
    """`add_person` creates `Unbestätigt` on first use and a blog post creates `Blog`. If the
    fixture seeded neither, the first write in any later test would move the tag count by one
    and read as a failure."""
    names = {tag["name"] for tag in imported.tags()}

    assert {"Blog", "Unbestätigt"} <= names
